import { Mail } from "lucide-react";
import type { ReactNode } from "react";
import { SettingsPanel } from "./SettingsPanel";
import styles from "./settings.module.css";
export function GmailConnection({
  email,
  connected,
  paused,
  pauseDetails,
  reconnectAction,
}: {
  email: string;
  connected: boolean;
  paused: boolean;
  pauseDetails?: ReactNode;
  reconnectAction: () => Promise<void>;
}) {
  return (
    <SettingsPanel id="gmail" title="Gmail connection" icon={Mail}>
      <div className="flex gap-3 items-center py-3.5 px-4 rounded-[var(--appearance-radius,_16px)] [background:var(--settings-inset)] [border:1px_solid_var(--settings-border)] [@media(width_<_480px)]:py-3.5 [@media(width_<_480px)]:px-3">
        <span
          className="grid place-items-center w-9.5 h-9.5 rounded-[50%] [background:var(--appearance-primary,_linear-gradient(_135deg,_var(--color-settings-settings-purple-21),_var(--color-settings-settings-pink-22)))] text-[var(--appearance-on-primary,_var(--color-settings-color-28))] font-extrabold flex-none"
          aria-hidden="true"
        >
          {email.charAt(0).toUpperCase()}
        </span>
        <div className="min-w-0">
          <p className="break-all text-sm font-bold">{email}</p>
          <p
            className={`flex gap-[7px] items-center mt-1 text-[13px] text-[var(--settings-green)] ${!connected || paused ? "text-[var(--settings-yellow)]" : ""}`}
          >
            <span
              className="flex-none w-[7px] h-[7px] rounded-full bg-current shadow-[var(--appearance-shadow,0_0_8px_currentColor)]"
              aria-hidden="true"
            />
            {connected
              ? paused
                ? "Connected · provider sending paused"
                : "Connected · sending enabled"
              : "Reconnect required · grant Gmail sending permission"}
          </p>
        </div>
      </div>
      {pauseDetails}
      <p
        className={`text-[var(--settings-muted)] text-[14px] leading-[1.65] mt-4`}
      >
        Mailloop sends from your Gmail. Mark replies and prepare follow-ups in
        History. Your refresh token is encrypted on the server. Reconnecting
        does not revoke old permissions. If Google still lists mailbox reading
        access, use Manage Access below to remove Mailloop access, then
        reconnect.
      </p>
      <div className="flex flex-wrap items-center gap-3.5 mt-6">
        <form action={reconnectAction}>
          <button
            className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
          >
            Reconnect Gmail
          </button>
        </form>
        <a
          href="https://myaccount.google.com/connections"
          className={`text-[var(--settings-purple)] font-semibold no-underline wrap-anywhere css-hover:underline inline-flex items-center min-h-11`}
        >
          Manage Access in Google
        </a>
      </div>
    </SettingsPanel>
  );
}
